BEGIN;
CREATE TABLE IF NOT EXISTS pooling.asset_anomaly(anomaly_id uuid PRIMARY KEY,asset_id uuid NOT NULL REFERENCES pooling.asset_position(asset_id),kind text NOT NULL CHECK(kind IN('SHARIA','ACCOUNTING')),reason text NOT NULL,detected_at timestamptz NOT NULL,status text NOT NULL CHECK(status IN('OPEN','RESOLVED')),resolved_at timestamptz,resolution_evidence_id text,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK(status<>'RESOLVED' OR(resolved_at IS NOT NULL AND resolution_evidence_id IS NOT NULL)));
CREATE INDEX IF NOT EXISTS asset_active_anomaly_idx ON pooling.asset_anomaly(asset_id,kind)WHERE status='OPEN';
ALTER TABLE pooling.asset_allocation_version DROP CONSTRAINT IF EXISTS asset_allocation_approval_fk;ALTER TABLE pooling.asset_allocation_version ADD CONSTRAINT asset_allocation_approval_fk FOREIGN KEY(approval_id)REFERENCES workflow.approval_action(idempotency_key);
CREATE OR REPLACE FUNCTION pooling.guard_asset_allocation_quality()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF EXISTS(SELECT 1 FROM pooling.asset_anomaly WHERE asset_id=NEW.asset_id AND status='OPEN')THEN RAISE EXCEPTION 'Asset is isolated by an active anomaly';END IF;IF EXISTS(SELECT 1 FROM pooling.asset_allocation_version WHERE asset_id=NEW.asset_id AND allocation_id<>NEW.allocation_id)THEN IF NEW.approval_id IS NULL OR NOT EXISTS(SELECT 1 FROM workflow.approval_action WHERE idempotency_key=NEW.approval_id AND resource_type='ASSET_ALLOCATION' AND resource_id=NEW.asset_id::text AND result_state='APPROVED')THEN RAISE EXCEPTION 'Reallocation requires approved decision';END IF;END IF;RETURN NEW;END;$$;DROP TRIGGER IF EXISTS asset_allocation_quality_guard ON pooling.asset_allocation_version;CREATE TRIGGER asset_allocation_quality_guard BEFORE INSERT OR UPDATE ON pooling.asset_allocation_version FOR EACH ROW EXECUTE FUNCTION pooling.guard_asset_allocation_quality();
COMMIT;
